  ('trinity', 'netball', 'Netball Court B', 2),
  ('trinity', 'frisbee', 'Sport Hall', 1),
  ('sugden', 'badminton', 'Hall C1', 1),
  ('sugden', 'badminton', 'Hall C2', 2),
  ('sugden', 'badminton', 'Hall C3', 3),
  ('sugden', 'badminton', 'Hall C4', 4),
  ('sugden', 'badminton', 'Hall D1', 5),
  ('sugden', 'badminton', 'Hall D2', 6),
